<?php
/** Pure 7.4-compatible product-command/policy tests; distinct from unchanged P1-C traces. */
require_once __DIR__.'/../includes/study-engine/engine.php';require_once __DIR__.'/../includes/study-engine/privacy/Policy.php';
use EIPSI\StudyEngine\Engine\Simulator;
use EIPSI\StudyEngine\Engine\DefinitionCompiler;
use EIPSI\StudyEngine\Privacy\Policy;
use EIPSI\StudyEngine\Contracts\Canonical;
$tests=0;$failed=0;
function gu_assert($v){if(!$v)throw new RuntimeException('Assertion failed');}
function gu_case($name,$fn){global $tests,$failed;$tests++;try{$fn();echo 'PASS G unit '.$name."\n";}catch(Throwable $e){$failed++;echo 'FAIL G unit '.$name.': '.$e->getMessage()."\n";}}
function gu_sim($fixture='03'){ $d=json_decode(file_get_contents(glob(__DIR__.'/study-engine/fixtures/valid/'.$fixture.'*.json')[0]),true);return new Simulator((new DefinitionCompiler())->compile($d),array('created_at'=>'2026-10-01T12:00:00Z','seed_hex'=>str_repeat('42',32),'execution_id'=>'G_UNIT'));}
function gu_withdraw($sim,$mode,$id='WITHDRAW'){return $sim->dispatch(array('id'=>$id,'kind'=>'WITHDRAW_EXECUTION','expected_revision'=>$sim->snapshot()['execution']['revision'],'data'=>array('mode'=>$mode,'source'=>'SESSION')));}
gu_case('B1 voluntary termination distinct from rule termination',function(){ $s=gu_sim();gu_withdraw($s,'RETAIN_FOR_ANALYSIS');gu_assert($s->snapshot()['execution']['state']==='WITHDRAWN'&&$s->snapshot()['withdrawal']['cleanup_state']==='NOT_REQUIRED');});
gu_case('B2 starts pending with DO_NOT_USE',function(){ $s=gu_sim();gu_withdraw($s,'DO_NOT_USE');gu_assert($s->snapshot()['withdrawal']['cleanup_state']==='PENDING'&&$s->snapshot()['withdrawal']['data_policy']==='DO_NOT_USE');});
gu_case('post-completion B2 preserves completion',function(){ $s=gu_sim('01');$b=$s->nextAction()['payload']['assessment_execution_id'];$answers=array();foreach($s->compiled()->definition()['nodes'] as $q)if($q['kind']==='QUESTION')$answers[$q['id']]=$q['type']==='INTEGER'?(int)($q['validation']['min']??1):($q['type']==='CHOICE'?$q['options'][0]['id']:'done');$s->dispatch(array('id'=>'COMPLETE','kind'=>'SUBMIT_ASSESSMENT','data'=>array('block_execution_id'=>$b,'responses'=>$answers)));gu_assert($s->snapshot()['execution']['state']==='COMPLETED');gu_withdraw($s,'DO_NOT_USE');gu_assert($s->snapshot()['execution']['state']==='COMPLETED');});
gu_case('post-rule termination B2 preserves reason',function(){ $s=gu_sim('02');$b=$s->nextAction()['payload']['assessment_execution_id'];$s->dispatch(array('id'=>'DECLINE','kind'=>'ANSWER','data'=>array('block_execution_id'=>$b,'question_id'=>'Q_CONSENT','value'=>'NO')));$before=$s->snapshot()['execution'];gu_assert($before['state']==='TERMINATED_BY_RULE');gu_withdraw($s,'DO_NOT_USE');gu_assert($s->snapshot()['execution']['state']===$before['state']&&$s->snapshot()['execution']['terminal_decision']===$before['terminal_decision']);});
gu_case('B1 to B2 same durable identity and stronger policy',function(){ $s=gu_sim();gu_withdraw($s,'RETAIN_FOR_ANALYSIS');$id=$s->snapshot()['withdrawal']['id'];gu_withdraw($s,'DO_NOT_USE','ESCALATE');gu_assert($s->snapshot()['withdrawal']['id']===$id&&$s->snapshot()['withdrawal']['mode']==='DO_NOT_USE');});
gu_case('B2 to B1 irreversible',function(){ $s=gu_sim();gu_withdraw($s,'DO_NOT_USE');$before=$s->snapshot();try{gu_withdraw($s,'RETAIN_FOR_ANALYSIS','DOWNGRADE');throw new RuntimeException('Accepted');}catch(DomainException $e){gu_assert(Canonical::json($before)===Canonical::json($s->snapshot()));}});
gu_case('identical command retry has no event or revision mutation',function(){ $s=gu_sim();$cmd=array('id'=>'RETRY','kind'=>'WITHDRAW_EXECUTION','expected_revision'=>0,'data'=>array('mode'=>'DO_NOT_USE','source'=>'SESSION'));$a=$s->dispatch($cmd);$before=$s->snapshot();$b=$s->dispatch($cmd);gu_assert($a===$b&&Canonical::json($before)===Canonical::json($s->snapshot()));});
gu_case('same command changed mode conflicts',function(){ $s=gu_sim();gu_withdraw($s,'RETAIN_FOR_ANALYSIS');try{gu_withdraw($s,'DO_NOT_USE');throw new RuntimeException('Accepted');}catch(DomainException $e){gu_assert(strpos($e->getMessage(),'IDEMPOTENCY_KEY_REUSED')!==false);}});
gu_case('terminal block history preserved while future closes',function(){ $s=gu_sim('06');$before=$s->snapshot()['instances'];gu_withdraw($s,'DO_NOT_USE');foreach($before as $id=>$b)gu_assert($s->snapshot()['instances'][$id]['state']===(Simulator::terminal($b['state'])?$b['state']:'WITHDRAWN'));});
gu_case('default analytical policy permits ordinary completion',function(){gu_assert(Policy::usable(array('state'=>'COMPLETED','data_policy'=>'USE_ALLOWED')));});
gu_case('retained policy obeys explicit analytical inclusion option',function(){gu_assert(Policy::usable(array('data_policy'=>'RETAIN_FOR_ANALYSIS'))&&!Policy::usable(array('data_policy'=>'RETAIN_FOR_ANALYSIS'),null,false));});
gu_case('B2 excludes immediately independent of cleanup state',function(){foreach(array('PENDING','FAILED','PARTIAL','COMPLETE_LOCAL') as $state)gu_assert(!Policy::usable(array('state'=>'COMPLETED'),array('data_policy'=>'DO_NOT_USE','cleanup_state'=>$state)));});
echo "$tests tests, $failed failures\n";exit($failed?1:0);
